import { readFileSync } from 'node:fs';
import { strFromU8, unzipSync } from 'fflate';
import { DEFAULT_FORM, detectForm, getForm } from './forms.js';

const SECTION_ENTRY = 'Contents/section0.xml';
const CAPTION_RE = /^그림\s*(\d+)\./u;

// Reads section0.xml only; this package currently assumes a single-section HWPX.
export function readSectionXml(hwpxPath) {
  const section = hwpxEntries(hwpxPath)[SECTION_ENTRY];
  if (!section) {
    throw new Error(`missing ${SECTION_ENTRY} in ${hwpxPath}`);
  }
  return strFromU8(section);
}

export function captionNumbers(xml) {
  const numbers = [];
  for (const { start, end } of paragraphRanges(xml)) {
    const text = ownParagraphText(xml, start, end);
    const match = CAPTION_RE.exec(text);
    if (match) {
      numbers.push(Number(match[1]));
    }
  }
  return numbers;
}

export function nextFigureNumber(xml) {
  const numbers = captionNumbers(xml);
  const seen = new Set();
  for (const number of numbers) {
    if (seen.has(number)) {
      throw new Error(`duplicate figure caption number: ${number}`);
    }
    seen.add(number);
  }
  return numbers.length === 0 ? 1 : Math.max(...numbers) + 1;
}

// The outline numbers already used in a document's body, so a continuation goes on from them:
// [heading1, heading2, heading3] counts after the last 가./1)/(1) label of the body.
const OUTLINE_LABELS = [/^([가-하])\.\s/u, /^(\d+)\)\s/u, /^\((\d+)\)\s/u];
const HANGUL_ORDINALS = '가나다라마바사아자차카타파하';
export function outlineCounters(xml, form) {
  const counters = [0, 0, 0];
  const { startIdx, endIdx } = bodyLocation(xml, form);
  // a "document" form's last paragraph is body text too when it is not the empty end paragraph
  const last = form.body.end === 'document' ? endIdx + 1 : endIdx;
  const paragraphs = topLevelParagraphRanges(xml).slice(startIdx, last);
  for (const { start, end } of paragraphs) {
    const text = ownParagraphText(xml, start, end).trimStart();
    OUTLINE_LABELS.some((re, level) => {
      const match = re.exec(text);
      if (!match) {
        return false;
      }
      counters[level] = level === 0 ? HANGUL_ORDINALS.indexOf(match[1]) + 1 : Number(match[1]);
      counters.fill(0, level + 1);
      return true;
    });
  }
  return counters;
}

// Where the body of a document of this form goes, as top-level paragraph indices:
//   startIdx  first body paragraph (after the form's startAfter paragraph or title)
//   endIdx    the paragraph the body is written before: the paragraph holding the body.end table,
//             or the last paragraph of the document for body.end "document"
//   endTable  { start, end } string offsets of the body.end table, or null
//   endEmpty  whether that last paragraph is empty (a "document" form writes before it only then)
// A body.end table is found by shape and header text (shape alone collides with content tables);
// it must be a top-level table. Documents whose body still sits in the old 1x1 box of the
// institute form (engine versions before 2026-09-29) are refused.
export function bodyLocation(xml, form) {
  const paragraphs = topLevelParagraphRanges(xml);
  if (paragraphs.length === 0) {
    throw new Error('the section has no paragraphs');
  }
  const bodyStart = () => {
    if (form.body.startAfter) {
      const heading = paragraphs.findIndex((p) => ownParagraphText(xml, p.start, p.end).includes(form.body.startAfter));
      if (heading < 0) {
        throw new Error(`form ${form.id}: no top-level paragraph contains "${form.body.startAfter}"`);
      }
      return heading + 1;
    }
    return form.title ? form.title.paragraph + 1 : 0;
  };
  if (form.body.end === 'document') {
    const startIdx = bodyStart();
    const endIdx = paragraphs.length - 1;
    const last = paragraphs[endIdx];
    const lastXml = xml.slice(last.start, last.end);
    const endEmpty = endIdx >= startIdx && !ownParagraphText(xml, last.start, last.end).trim()
      && !/<hp:(?:tbl|pic|secPr)\b/.test(lastXml);
    return { startIdx, endIdx, endTable: null, endEmpty };
  }
  const spec = form.body.end.table;
  const tables = tableRanges(xml);
  const end = requireUnique(
    tables.filter((table) => table.attrs.rowCnt === String(spec.rows)
      && table.attrs.colCnt === String(spec.cols)
      && spec.header.every((needle) => xml.slice(table.start, table.end).includes(needle))),
    `${spec.rows}x${spec.cols} table with header ${spec.header.join('/')} (form ${form.id})`,
  );
  const boxed = tables.some((table) => table.attrs.rowCnt === '1' && table.attrs.colCnt === '1'
    && end.start > table.start && end.end < table.end);
  if (boxed) {
    throw new Error('the body sits in the old 1x1 box of the form; regenerate the report from '
      + 'the current form skeleton (the body is now written outside any table)');
  }
  if (tables.some((table) => table.start < end.start && end.end < table.end)) {
    throw new Error(`form ${form.id}: the body.end table must be a top-level table`);
  }
  const endIdx = paragraphs.findIndex((p) => p.start <= end.start && end.start < p.end);
  return { startIdx: bodyStart(), endIdx, endTable: { start: end.start, end: end.end }, endEmpty: false };
}

// Kept for callers that check whether a document is one the engine can continue: the body
// location of the detected form, with the institute form's summary-table offsets when present.
export function anchorInfo(xml) {
  const location = bodyLocation(xml, detectForm(xml));
  return {
    ...location,
    // Offsets are JS string indices into this decoded XML string; compare only
    // against offsets from the same string.
    summaryTableIndex: location.endTable?.start ?? null,
    summaryTableEnd: location.endTable?.end ?? null,
  };
}

// Top-level paragraphs of the section (not inside a table or another paragraph), in document order.
// Shared with the engine: bodyLocation indices and the paragraphs the engine writes must agree.
export function topLevelParagraphRanges(xml) {
  return paragraphRangesWithTableDepth(xml).filter((paragraph) => paragraph.tableDepth === 0
    && paragraph.nested === false);
}

function paragraphRangesWithTableDepth(xml) {
  const ranges = [];
  const stack = [];
  const tokenRe = /<hp:p(?=[\s/>])[^>]*>|<\/hp:p>|<hp:tbl(?=[\s/>])[^>]*>|<\/hp:tbl>/g;
  let tableDepth = 0;
  let match;
  while ((match = tokenRe.exec(xml)) !== null) {
    const token = match[0];
    if (token.startsWith('<hp:p')) {
      if (isSelfClosingTag(token)) {
        ranges.push({ start: match.index, end: tokenRe.lastIndex, tableDepth, nested: stack.length > 0 });
      } else {
        stack.push({ start: match.index, tableDepth, nested: stack.length > 0 });
      }
    } else if (token === '</hp:p>') {
      const start = stack.pop();
      if (start === undefined) {
        throw new Error(`unexpected closing paragraph tag at ${match.index}`);
      }
      ranges.push({ start: start.start, end: tokenRe.lastIndex, tableDepth: start.tableDepth, nested: start.nested });
    } else if (token.startsWith('<hp:tbl')) {
      if (!isSelfClosingTag(token)) {
        tableDepth += 1;
      }
    } else if (token === '</hp:tbl>') {
      tableDepth -= 1;
    }
  }
  if (stack.length > 0) {
    throw new Error(`unclosed paragraph tag at ${stack[stack.length - 1].start}`);
  }
  return ranges.sort((a, b) => a.start - b.start);
}


// rhwp exportHwpx parses <hh:bullets> but never re-serializes it, which leaves the
// paraPr 59-61 heading idRefs dangling (Hancom then renders its own fallback marker -
// the duplicated-bullet symptom). Restore the sample-verbatim container after export.
const BULLET_DEFS_PARA_HEAD = '<hh:paraHead level="0" align="LEFT" useInstWidth="0" autoIndent="1" widthAdjust="0" textOffsetType="PERCENT" textOffset="50" numFormat="DIGIT" charPrIDRef="4294967295" checkable="0"/>';
export const BULLET_DEFS_XML = '<hh:bullets itemCnt="3">'
  + `<hh:bullet id="1" char="◎" useImage="0">${BULLET_DEFS_PARA_HEAD}</hh:bullet>`
  + `<hh:bullet id="2" char="⚪" useImage="0">${BULLET_DEFS_PARA_HEAD}</hh:bullet>`
  + `<hh:bullet id="3" char="\u00ad" useImage="0">${BULLET_DEFS_PARA_HEAD}</hh:bullet>`
  + '</hh:bullets>';

// The header with the engine's bullet container added when it is missing (rhwp drops it on export).
export function withEngineBullets(header) {
  if (header.includes('<hh:bullets')) {
    return header;
  }
  const anchorTag = '</hh:numberings>';
  if (!header.includes(anchorTag)) {
    throw new Error('header.xml missing </hh:numberings>; cannot restore bullet definitions');
  }
  return header.replace(anchorTag, `${anchorTag}${BULLET_DEFS_XML}`);
}

// The paragraph, character, style and border definitions the engine writes with, by ID. Every
// form skeleton shares them; a document whose definitions under these IDs differ (another
// institute's file, an edited header) would get the engine's text in the wrong look, so the
// engine does not continue it. The comparison follows references: a style's paraPr/charPr, a
// charPr's fonts (per language) and border, a paraPr's tab and border definitions and its
// heading numbering or bullet, so a changed font or tab under an unchanged ID is caught too.
const ENGINE_STYLE_IDS = { paraPr: [5, 57, 58, 59, 60, 61, 62], charPr: [6, 46, 50, 53], style: [0, 22],
  borderFill: [4, 15, 17] };
const FONT_LANGS = { hangul: 'HANGUL', latin: 'LATIN', hanja: 'HANJA', japanese: 'JAPANESE', other: 'OTHER',
  symbol: 'SYMBOL', user: 'USER' };
let baseHeader;

function styleDefinition(header, tag, id) {
  const re = new RegExp(`<hh:${tag} id="${id}"[^>]*?(?:/>|>[\\s\\S]*?</hh:${tag}>)`);
  return re.exec(header)?.[0] ?? null;
}

function fontDefinition(header, lang, id) {
  const face = new RegExp(`<hh:fontface lang="${lang}"[^>]*>([\\s\\S]*?)</hh:fontface>`).exec(header)?.[1];
  return face ? styleDefinition(face, 'font', id) : null;
}

const attr = (xml, name) => new RegExp(`\\b${name}="([^"]*)"`).exec(xml)?.[1];

// definitions a definition points to, as [tag, id] (fonts as ['font:<LANG>', id])
function references(tag, xml) {
  const refs = [];
  if (tag === 'style') {
    refs.push(['paraPr', attr(xml, 'paraPrIDRef')], ['charPr', attr(xml, 'charPrIDRef')]);
  } else if (tag === 'charPr') {
    refs.push(['borderFill', attr(xml, 'borderFillIDRef')]);
    const fontRef = /<hh:fontRef ([^>]*)\/>/.exec(xml)?.[1] ?? '';
    for (const [key, lang] of Object.entries(FONT_LANGS)) {
      refs.push([`font:${lang}`, attr(fontRef, key)]);
    }
  } else if (tag === 'paraPr') {
    refs.push(['tabPr', attr(xml, 'tabPrIDRef')]);
    refs.push(['borderFill', attr(/<hh:border [^>]*>/.exec(xml)?.[0] ?? '', 'borderFillIDRef')]);
    const heading = /<hh:heading ([^>]*)\/>/.exec(xml)?.[1] ?? '';
    const kind = attr(heading, 'type');
    if (kind === 'NUMBER' || kind === 'OUTLINE') {
      refs.push(['numbering', attr(heading, 'idRef')]);
    } else if (kind === 'BULLET') {
      refs.push(['bullet', attr(heading, 'idRef')]);
    }
  }
  return refs.filter(([, id]) => id !== undefined);
}

function definition(header, tag, id) {
  return tag.startsWith('font:') ? fontDefinition(header, tag.slice(5), id) : styleDefinition(header, tag, id);
}

export function styleMismatches(headerXml) {
  baseHeader ??= withEngineBullets(
    strFromU8(unzipSync(readFileSync(getForm(DEFAULT_FORM).skeleton))['Contents/header.xml']));
  // a document straight from a skeleton has no bullet container yet; the engine adds the same one
  const header = headerXml.includes('</hh:numberings>') ? withEngineBullets(headerXml) : headerXml;
  const mismatches = [];
  const seen = new Set();
  const queue = Object.entries(ENGINE_STYLE_IDS).flatMap(([tag, ids]) => ids.map((id) => [tag, String(id)]));
  while (queue.length > 0) {
    const [tag, id] = queue.shift();
    const key = `${tag} ${id}`;
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);
    const expected = definition(baseHeader, tag, id);
    if (definition(header, tag, id) !== expected) {
      mismatches.push(key);
    } else if (expected) {
      queue.push(...references(tag, expected));
    }
  }
  return mismatches;
}

export function readHeaderXml(hwpxPath) {
  const header = hwpxEntries(hwpxPath)['Contents/header.xml'];
  if (!header) {
    throw new Error(`missing Contents/header.xml in ${hwpxPath}`);
  }
  return strFromU8(header);
}

export function binDataEntries(hwpxPath) {
  return Object.keys(hwpxEntries(hwpxPath))
    .filter((name) => name.startsWith('BinData/') && !name.endsWith('/'))
    .sort();
}

function hwpxEntries(hwpxPath) {
  return unzipSync(readFileSync(hwpxPath));
}

function paragraphRanges(xml) {
  return tagRanges(xml, 'hp:p', 'paragraph');
}

function tableRanges(xml) {
  const tables = [];
  const headerRe = /<hp:tbl(?=[\s/>])[^>]*>/g;
  let match;
  while ((match = headerRe.exec(xml)) !== null) {
    tables.push({
      start: match.index,
      end: tagEnd(xml, 'hp:tbl', match.index, 'table'),
      attrs: parseAttrs(match[0]),
    });
  }
  return tables;
}

function tagRanges(xml, tagName, label) {
  const ranges = [];
  const stack = [];
  const tokenRe = tagTokenRe(tagName);
  let match;
  while ((match = tokenRe.exec(xml)) !== null) {
    const token = match[0];
    if (isCloseTag(token)) {
      const start = stack.pop();
      if (start === undefined) {
        throw new Error(`unexpected closing ${label} tag at ${match.index}`);
      }
      ranges.push({ start, end: tokenRe.lastIndex });
    } else if (isSelfClosingTag(token)) {
      ranges.push({ start: match.index, end: tokenRe.lastIndex });
    } else {
      stack.push(match.index);
    }
  }
  if (stack.length > 0) {
    throw new Error(`unclosed ${label} tag at ${stack[stack.length - 1]}`);
  }
  return ranges.sort((a, b) => a.start - b.start);
}

function tagEnd(xml, tagName, start, label) {
  const tokenRe = tagTokenRe(tagName);
  tokenRe.lastIndex = start;
  let depth = 0;
  let match;
  while ((match = tokenRe.exec(xml)) !== null) {
    const token = match[0];
    if (isCloseTag(token)) {
      depth -= 1;
      if (depth === 0) {
        return tokenRe.lastIndex;
      }
      if (depth < 0) {
        break;
      }
    } else if (isSelfClosingTag(token)) {
      if (depth === 0) {
        return tokenRe.lastIndex;
      }
    } else {
      depth += 1;
    }
  }
  throw new Error(`unclosed ${label} tag at ${start}`);
}

function tagTokenRe(tagName) {
  return new RegExp(`<${tagName}(?=[\\s/>])[^>]*>|</${tagName}>`, 'g');
}

function ownParagraphText(xml, start, end) {
  const tokenRe = /<hp:p(?=[\s/>])[^>]*>|<\/hp:p>|<hp:t(?=[\s/>])[^>]*\/>|<hp:t(?=[\s/>])[^>]*>[\s\S]*?<\/hp:t>/g;
  tokenRe.lastIndex = start;

  let depth = 0;
  let text = '';
  let match;
  while ((match = tokenRe.exec(xml)) !== null && match.index < end) {
    const token = match[0];
    if (token.startsWith('<hp:p')) {
      if (!isSelfClosingTag(token)) {
        depth += 1;
      }
    } else if (token === '</hp:p>') {
      depth -= 1;
      if (depth === 0) {
        break;
      }
    } else if (depth === 1 && !isSelfClosingTag(token)) {
      text += token.replace(/^<hp:t(?=[\s/>])[^>]*>/, '').replace(/<\/hp:t>$/, '');
    }
  }
  return text;
}

function parseAttrs(header) {
  const attrs = {};
  const attrRe = /([\w:-]+)="([^"]*)"/g;
  let match;
  while ((match = attrRe.exec(header)) !== null) {
    attrs[match[1]] = match[2];
  }
  return attrs;
}

function requireUnique(items, label) {
  if (items.length !== 1) {
    throw new Error(`${label} must be unique; found ${items.length}`);
  }
  return items[0];
}

function isCloseTag(token) {
  return token.startsWith('</');
}

function isSelfClosingTag(token) {
  return token.endsWith('/>');
}
